267	    public String getSelfLink() {
268	        return "/api/owners/" + this.getId();
269	    }
270	
271	    /**
272	     * Return whether this owner is a possible duplicate: true when it was created while an existing
273	     * owner already shared its last name and postcode under a different telephone, i.e. when a
274	     * {@link #getPossibleDuplicateOf() possible-duplicate-of} owner id is present.
275	     */
276	    @Transient
277	    public boolean getPossibleDuplicate() {
278	        return this.possibleDuplicateOf != null;
279	    }
280	
281	    /**
282	     * Return this owner's name formatted as {@code LastName, FirstName}.
283	     */
284	    @Transient
285	    public String getDisplayName() {
286	        return this.getLastName() + ", " + this.getFirstName();
287	    }
288	
289	    /**
290	     * Return this owner's salutation: the {@link #getTitle() title} followed by a space and the
291	     * last name (e.g. {@code DR Franklin}), or just the last name when no title was supplied.
292	     */
293	    @Transient
294	    public String getSalutation() {
295	        if (this.title == null || this.title.isBlank()) {
296	            return this.getLastName();
297	        }
298	        return this.title + " " + this.getLastName();
299	    }
300	
301	    /**
302	     * Return this owner's telephone formatted for human display: the country code, a space, then
303	     * the national digits grouped in threes (e.g. {@code '+61 412 345 678'}). The raw
304	     * {@link #getTelephone() telephone} remains in canonical E.164 form.
305	     */
306	    @Transient
307	    public String getTelephoneDisplay() {
308	        return TelephoneFormatter.format(this.telephone);
309	    }
310	
311	    /**
312	     * Return this owner's identity key: the derived value formed as
313	     * {@code normalizedTelephone + '|' + email + '|' + householdId} (an absent email or household id
314	     * contributes an empty segment). Members of the same household share a household id but, having
315	     * different telephones, still have distinct identity keys. The telephone and email are expected
316	     * to already be in their normalized storage form.
317	     */
318	    @Transient
319	    public String getIdentityKey() {
320	        return orEmpty(this.telephone) + "|" + orEmpty(this.email) + "|" + orEmpty(this.householdId);
321	    }
322	
323	    private static String orEmpty(String value) {
