179	    /** Validate, derive and persist a brand-new owner from the submitted fields. */
180	    private Owner createOwner(OwnerFieldsDto ownerFieldsDto) {
181	        normalizeAddress(ownerFieldsDto);
182	        OwnerFieldsValidator.validateRequiredFields(ownerFieldsDto);
183	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
184	        owner.setTelephone(TelephoneNormalizer.normalize(owner.getTelephone()));
185	        owner.setEmail(EmailNormalizer.normalize(owner.getEmail()));
186	        DisposableEmailDomainValidator.validate(owner.getEmail());
187	        PostcodeValidator.validate(owner.getCity(), owner.getPostcode());
188	        RegistrationDateValidator.validateNotFuture(owner.getRegistrationDate());
189	        LocalDate effectiveDate = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
190	        owner.setRegistrationDate(BusinessDayAdjuster.toBusinessDay(effectiveDate));
191	        this.dailyRegistrationCapacityValidator.validateHasCapacity(owner.getRegistrationDate());
192	        owner.setHouseholdId(HouseholdKey.idFor(owner.getLastName(), owner.getPostcode()));
193	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
194	            // Reject only a true duplicate (an owner identical to one already on file); a distinct
195	            // new household member is allowed but flagged as a possible duplicate. A declared member
196	            // bypasses this block, and is not a suspected duplicate.
197	            this.householdDuplicateValidator.rejectIfDuplicate(owner);
198	            this.possibleDuplicateOwnerDetector.findPossibleDuplicateOf(owner)
199	                .ifPresent(owner::setPossibleDuplicateOf);
200	        }
201	        this.cityOwnerCapacityValidator.validateHasCapacity(owner.getCity());
202	        owner.setNamesakeCount(this.namesakeCounter.count(owner.getFirstName(), owner.getLastName()));
203	        owner.setHouseholdSize(this.householdSizeCounter.count(owner.getHouseholdId()));
204	        owner.setMembershipLevelCap(this.householdMembershipLevelCap.ceilingFor(owner.getHouseholdId()));
