208	        this.clinicService.saveOwner(owner);
209	        owner.setMembershipNumber(MembershipNumberGenerator.generate(owner.getCustomerCode(), owner.getRegistrationDate()));
210	        this.ownerAuditLogger.logCreated(owner);
